function UIPolePlotCGCollectPopupDialog:Awake()
    local argument = self.controller.Argument.parameters
    if argument then
        self._curChapterId = checkNumber(argument.id)  --副本类型
    end

    if checkNumber(self._curChapterId) == 0 then
        return
    end

    self:InitData()
    self:FillSelf()

    SetButtonAction(self.controller.gameObject.transform:Find("Fuzzy"), function()
        self:OnBtnClose()
    end)
end

function UIPolePlotCGCollectPopupDialog:InitData()
    self._allOverFinaleId = QuestConfMgr:GetInstance():GetRoleStoryOverFinaleCgIds(self._curChapterId)
end

function UIPolePlotCGCollectPopupDialog:FillSelf()
    if not self._isInit then
        self._isInit = true
        self.ListContent:InitGridView(#self._allOverFinaleId, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ListContent, #self._allOverFinaleId)
    end
end

function UIPolePlotCGCollectPopupDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local id = self._allOverFinaleId[index + 1]
    local vo = QuestConfMgr:GetInstance():GetRoleStoryOverFinaleCgVo(id)
    self:FillCgInfo(cell.gameObject, vo, index + 1)
    return cell
end

function UIPolePlotCGCollectPopupDialog:FillCgInfo(go, data, ind)
    if not go or not data then
        return
    end

    local isHas = QuestConfMgr:GetInstance():IsHasOverFinaleId(data.id)
    CfUtils.SetActive(go.transform:Find("Lock"), not isHas)
    CfUtils.SetActive(go.transform:Find("Normal"), isHas)

    if isHas then
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(data.chapterId)
        
        CfUtils.FillText(go.transform:Find("Normal/TxtTitle"), vo.name)
        CfUtils.FillImage(go.transform:Find("Normal/ImgCgSmall"), data.cgIcon)
    else

    end

    for i = 1, 5 do
        local titleGo = go.transform:Find("ImgTiao"..i)
        if titleGo then
            CfUtils.SetActive(titleGo, ind == i)
        end
    end

    SetButtonAction(go, function()
        CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIPolePlotCGEndingDialog, parameters = {id = data.id, type = 1}},  {
            --{id = Constants.UITypeIds.UIMainBattlePanelDialog}
        })
    end)
end

